function ensureTenLessonQuestions(lesson){
  const qs=[...lesson.quiz];
  let p=0;
  while(qs.length<10){
    const idx=(p+3)%lesson.phrases.length;
    const [de,fr]=lesson.phrases[idx];
    const distract=[];
    for(let k=1;k<lesson.phrases.length&&distract.length<2;k++){
      const candidate=lesson.phrases[(idx+k)%lesson.phrases.length][1];
      if(candidate!==fr&&!distract.includes(candidate))distract.push(candidate);
    }
    const pos=qs.length%3;
    const opts=[...distract];opts.splice(pos,0,fr);
    qs.push({q:`Que signifie « ${de} » ?`,o:opts,a:pos,audio:de});
    p++;
  }
  lesson.quiz=qs.slice(0,10);
}
lessons.forEach(ensureTenLessonQuestions);

