const stateKey=A1Profile.namespacedKey('deutschA1GoetheFormatState_v6');
const defaultState={doneLessons:[],lessonWork:{},masteredListening:[],masteredReading:[],writingDone:[],speakingDone:[],lessonQuizBest:{},grammarBest:{},lessonGrammarPractice:{},lessonGrammarCheckBest:{},lessonGrammarCheckLast:{},lessonMasteryBest:{},lessonMasteryLast:{},courseMasteryBest:{},practiceDone:{grammar:[],listening:[],reading:[]},vocabKnown:[],bestMock:0};
function loadState(){
  const loaded=A1Learning.loadState(stateKey,defaultState);
  if(DE_A1_ASSESSMENTS.completePassedLessons(loaded,lessons)){
    A1Profile.saveProgress('deutsch-a1',loaded,Math.round(loaded.doneLessons.length/lessons.length*100));
  }
  return loaded;
}

let state=loadState();
function save(completed=false){if(completed)A1Streak.completeExercise();DE_A1_ASSESSMENTS.completePassedLessons(state,lessons);localStorage.setItem(stateKey,JSON.stringify(state));A1Profile.saveProgress('deutsch-a1',state,lessonPct());}

let audioEnabled=localStorage.getItem('deA1AudioEnabled')!=='false';
let currentRoute='home';
let activeRecorder=null;
const view=document.getElementById('view');
const navButtons=[...document.querySelectorAll('.nav-item')];
const audioToggle=document.getElementById('audioToggle');
const practiceProgress=A1PracticeProgress.create({
  lang:'fr',lessons,grammarSets,listening,reading,forms:formTasks,writing:emailTasks,
  speaking:{
    interview:interviewQuestions.map(x=>'intro-'+x.q),
    info:speakingTopics.flatMap(t=>t.cards.map(x=>'info-'+t.theme+'-'+x.cue)),
    requests:requestCards.map(x=>'req-'+x.cue)
  },
  bindings:{
    '#pVocab':'vocab','#pGrammar':'grammar','#pHear':'listening','#pRead':'reading','#pWrite':'writing','#pSpeak':'speaking',
    '[data-part="1"]':'listening:1','[data-part="2"]':'listening:2','[data-part="3"]':'listening:3','[data-part="4"]':'listening:4',
    '[data-rpart="1"]':'reading:1','[data-rpart="2"]':'reading:2','[data-rpart="3"]':'reading:3',
    '#formPractice':'forms','#emailPractice':'messages',
    '[data-spart="1"]':'speaking:interview','[data-spart="2"]':'speaking:info','[data-spart="3"]':'speaking:requests'
  },getState:()=>state,save,view:()=>view
});

function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
function unique(arr){return [...new Set(arr)];}
function randomItem(arr){return arr[Math.floor(Math.random()*arr.length)];}
function shuffle(arr){return A1Learning.shuffle(arr);}
function normalize(s=''){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9@.]+/g,' ').trim().replace(/\s+/g,' ');}
function lessonPct(){return Math.round(state.doneLessons.length/lessons.length*100);}
function totalListening(){return Object.values(listening).reduce((n,a)=>n+a.length,0);}
function totalReading(){return Object.values(reading).reduce((n,a)=>n+a.length,0);}
function totalInfoCards(){return speakingTopics.reduce((n,t)=>n+t.cards.length,0);}
function overallCompletionPct(){
  const lessonDone=(state.doneLessons||[]).length;
  const grammarDone=Object.values(state.grammarBest||{}).filter(v=>Number(v)>0).length;
  const done=lessonDone+grammarDone+state.masteredListening.length+state.masteredReading.length+state.writingDone.length+new Set(state.speakingDone).size;
  const total=lessons.length+grammarSets.length+totalListening()+totalReading()+formTasks.length+emailTasks.length+interviewQuestions.length+totalInfoCards()+requestCards.length;
  return Math.round(clamp(done/Math.max(total,1)*100,0,100));
}
window.A1CourseProgressPercent=lessonPct;
function skillPct(kind){
  if(kind==='Hören') return Math.round(clamp(state.masteredListening.length/totalListening()*100,0,100));
  if(kind==='Lesen') return Math.round(clamp(state.masteredReading.length/totalReading()*100,0,100));
  if(kind==='Schreiben') return Math.round(clamp(state.writingDone.length/(formTasks.length+emailTasks.length)*100,0,100));
  if(kind==='Sprechen') return Math.round(clamp(state.speakingDone.length/(interviewQuestions.length+totalInfoCards()+requestCards.length)*100,0,100));
  return 0;
}
function readiness(){return Math.round((skillPct('Hören')+skillPct('Lesen')+skillPct('Schreiben')+skillPct('Sprechen'))/4);}
function updateAudioButton(){audioToggle.textContent=audioEnabled?'🔊 Auto':'🔇 Auto';audioToggle.classList.toggle('audio-off',!audioEnabled);}
function speak(text,force=false,rate=.82){if((!audioEnabled&&!force)||!text)return;A1Voice.speak(text,{lang:'de-DE',rate});}
function playCorrectAudio(text,force=false){if((!audioEnabled&&!force)||!text)return;speak(text,true,.80);}
function speakBtn(text,label='Écouter la prononciation'){return `<button class="speak-btn" data-speak="${esc(text)}" aria-label="${esc(label)}">🔊</button>`;}
function wireSpeakButtons(){document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak,true));}
function setRoute(route){currentRoute=route;navButtons.forEach(b=>b.classList.toggle('active',b.dataset.route===route)); if(route==='home')renderHome(); if(route==='learn')renderLearn(); if(route==='practice')renderPractice(); if(route==='exam')renderExam(); window.scrollTo({top:0,behavior:'smooth'});}

function skillBar(name,emoji){const p=skillPct(name);const labels={
  Hören:'Écoute',
  Lesen:'Lecture',
  Schreiben:'Écriture',
  Sprechen:'Oral'
};
                              return `<div class="skill-row"><strong>${emoji} ${labels[name]||name}</strong><div class="progress"><div style="width:${p}%"></div></div><span>${p}%</span></div>`;}

function renderHome(){
  const next=lessons.find(l=>!state.doneLessons.includes(l.id))||lessons[lessons.length-1];
  view.innerHTML=`
    <section class="card course-progress-card" data-streak-anchor>
      <h2>Progression du cours</h2>
      <p class="course-progress-caption">Français → Allemand · Goethe A1</p>
      <div class="course-progress-meter"><strong>${lessonPct()}<small>%</small></strong><div class="progress" role="progressbar" aria-label="Progression du cours" aria-valuenow="${lessonPct()}" aria-valuemin="0" aria-valuemax="100"><div style="width:${lessonPct()}%"></div></div></div>
      <div class="course-progress-stats"><div><strong>${state.doneLessons.length}<small> / ${lessons.length}</small></strong><span>Leçons terminées</span></div><div><strong>${DE_A1_ASSESSMENTS.passedCount(state)}<small> / ${lessons.length}</small></strong><span>Bilans effectués</span></div></div>
    ${A1Streak.render('fr')}</section>
    <section class="card">
      <div class="between"><div><div class="eyebrow">CONTINUER</div><h3 style="margin-top:5px">${next.id}. ${esc(next.title)}</h3><p class="muted">${esc(next.note)}</p></div><span class="pill">${lessonPct()}%</span></div>
      <button class="primary-btn" id="continueLesson">Continuer le cours</button>
    </section>
    <section class="card">
      <div class="between"><h3>Prêt pour l’examen</h3><span class="pill gray">${state.bestMock}% meilleur test</span></div>
      ${skillBar('Hören','🎧')}${skillBar('Lesen','📖')}${skillBar('Schreiben','✍️')}${skillBar('Sprechen','🎤')}
    </section>`;
  document.getElementById('continueLesson').onclick=()=>renderLesson(next.id);
}

function renderLearn(){
  view.innerHTML=`<section class="card hero"><span class="pill">${lessons.length} LEÇONS · EXERCICES + BILAN</span><h2 style="margin-top:12px">Cours d’allemand A1</h2><p class="muted">Ce cours te prépare de façon ciblée au Goethe-Zertifikat A1. ${DE_A1_ASSESSMENTS.passedCount(state)} / ${lessons.length} bilans effectués.</p><div class="progress"><div style="width:${lessonPct()}%"></div></div></section><div class="list">${lessons.map(l=>`<button class="lesson ${state.doneLessons.includes(l.id)?'done':''}" data-lesson="${l.id}"><div><span class="num">${l.id}</span><strong>${esc(l.title)}</strong></div><p class="lesson-goal-preview">${A1LessonGuide.goal(l.id,esc)}</p><div class="lesson-meta lesson-progress-meta">${A1LessonFlow.listProgress(l,state,'fr')}</div></button>`).join('')}</div>`;
  document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>renderLesson(+b.dataset.lesson));
}


