function renderGrammarIntro(id){
  const set=grammarSets.find(x=>x.id===id);
  if(!set)return renderGrammarMenu();
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backGrammarIntro">← Grammaire</button><span class="pill">${esc(set.title)}</span></div><section class="card" style="margin-top:12px"><h2>${esc(set.title)}</h2><p class="muted">${esc(set.subtitle)}</p><hr class="soft">${A1GrammarUI.reorderGuide(GRAMMAR_GUIDES[id]||'')}<div class="grammar-study-hint">💡 Ouvre les tableaux si tu veux vérifier une forme. Les informations nécessaires aux exercices suivants sont disponibles sur cette page.</div><div class="spacer"></div><button class="primary-btn" id="startGrammarPractice">Commencer les 10 questions</button></section>`;
  document.getElementById('backGrammarIntro').onclick=renderGrammarMenu;
  document.getElementById('startGrammarPractice').onclick=()=>startGrammarSet(id);
}

function renderGrammarMenu(){
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backPractice">← Entraîner</button><span class="pill">🧩 Grammaire</span></div><section class="card hero" style="margin-top:12px"><h2>Grammaire & structures A1</h2><p class="muted">8 séries de 10 questions sur les structures utiles au niveau A1.</p></section><div class="list">${grammarSets.map(s=>`<button class="practice-card" data-gset="${s.id}"><strong>${esc(s.title)}</strong><small>${esc(s.subtitle)} · meilleur résultat ${state.grammarBest[s.id]||0}%</small></button>`).join('')}</div>`;
  document.getElementById('backPractice').onclick=renderPractice;document.querySelectorAll('[data-gset]').forEach(b=>b.onclick=()=>renderGrammarIntro(b.dataset.gset));
  practiceProgress.decorate();
}

function startGrammarSet(id){
  const set=grammarSets.find(x=>x.id===id),qs=shuffle(set.questions).slice(0,10);let i=0,score=0;
  function draw(){
    if(i>=qs.length){const pct=Math.round(score/qs.length*100);state.grammarBest[id]=Math.max(state.grammarBest[id]||0,pct);save(true);view.innerHTML=`<section class="card center"><span class="pill ${pct>=70?'green':'amber'}">${esc(set.title)}</span><div class="score">${pct}%</div><h2>${score}/${qs.length}</h2><p class="muted">La bonne réponse est lue après chaque réponse.</p><div class="button-row"><button class="secondary-btn" id="againGrammar">Recommencer</button><button class="primary-btn" id="backGrammar">Toutes les séries</button></div></section>`;document.getElementById('againGrammar').onclick=()=>startGrammarSet(id);document.getElementById('backGrammar').onclick=renderGrammarMenu;return;}
    const q=qs[i];view.innerHTML=`<div class="between"><button class="tiny-btn" id="backGrammar">← Grammaire</button><span class="pill">${i+1}/${qs.length}</span></div><section class="card" style="margin-top:12px"><div class="eyebrow">${esc(set.title)}</div><div class="quiz-q">${esc(q.q)}</div><div class="options">${q.o.map((o,j)=>`<button class="option-btn" data-o="${j}">${esc(o)}</button>`).join('')}</div><div id="grammarFeedback"></div></section>`;document.getElementById('backGrammar').onclick=renderGrammarMenu;document.querySelectorAll('[data-o]').forEach(btn=>btn.onclick=()=>{const chosen=+btn.dataset.o,ok=chosen===q.a;if(ok)score++;if(q.audio)playCorrectAudio(q.audio,true);practiceProgress.recordGrammar(set,q);document.querySelectorAll('[data-o]').forEach((b,j)=>{b.disabled=true;if(j===q.a)b.classList.add('correct');else if(j===chosen)b.classList.add('wrong');});document.getElementById('grammarFeedback').innerHTML=`<div class="feedback ${ok?'good':'bad'}">${ok?'✓ Correct':'✗ Bonne réponse : '+esc(q.o[q.a])}</div><div class="spacer"></div><button class="primary-btn" id="nextGrammar">${i<qs.length-1?'Suivant':'Résultat'}</button>`;document.getElementById('nextGrammar').onclick=()=>{i++;draw();};});
  }
  draw();
}

function renderVocab(){const cards=lessons.flatMap(l=>l.phrases.map(([de,fr])=>({de,fr,lesson:l.id})));let idx=+localStorage.getItem(A1Profile.namespacedKey('deA1VocabIndex'))||0;let reveal=false;function draw(){const c=cards[idx%cards.length];view.innerHTML=`<div class="between"><button class="tiny-btn" id="backPractice">← Entraîner</button><span class="pill">${idx%cards.length+1}/${cards.length}</span></div><section class="card center" style="margin-top:12px"><div class="eyebrow">LEÇON ${c.lesson}</div><div style="display:flex;justify-content:center;align-items:center;gap:12px;margin:25px 0 8px"><div style="font-size:31px;font-weight:900">${esc(c.de)}</div>${speakBtn(c.de)}</div>${reveal?`<div class="translation">${esc(c.fr)}</div>`:'<p class="muted">Trouve le sens en français.</p>'}${!reveal?'<button class="primary-btn" id="reveal">Afficher la réponse</button>':'<div class="button-row"><button class="secondary-btn" id="again">À revoir</button><button class="primary-btn" id="known">Je savais ✓</button></div>'}</section>`;wireSpeakButtons();document.getElementById('backPractice').onclick=renderPractice;if(!reveal)document.getElementById('reveal').onclick=()=>{reveal=true;draw();};else{document.getElementById('again').onclick=()=>{practiceProgress.markVocab(c.lesson,c.de,c.fr,false);A1Streak.completeExercise();idx=(idx+1)%cards.length;reveal=false;localStorage.setItem(A1Profile.namespacedKey('deA1VocabIndex'),idx);draw();};document.getElementById('known').onclick=()=>{practiceProgress.markVocab(c.lesson,c.de,c.fr,true);A1Streak.completeExercise();idx=(idx+1)%cards.length;reveal=false;localStorage.setItem(A1Profile.namespacedKey('deA1VocabIndex'),idx);draw();};}if(audioEnabled)setTimeout(()=>speak(c.de),180);}draw();}

function renderListeningMenu(){
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backPractice">← Entraîner</button><span class="pill">🎧 Écoute</span></div><section class="card hero" style="margin-top:12px"><h2>Écoute</h2><p class="muted">Chaque ronde contient 10 tâches. Les trois premières séries reprennent les formats Goethe; la quatrième est un entraînement A1 supplémentaire.</p></section><div class="list"><button class="practice-card" data-part="1"><strong>Partie 1 · a / b / c</strong><small>Courts dialogues · pool ${listening[1].length}.</small></button><button class="practice-card" data-part="2"><strong>Partie 2 · Vrai / Faux</strong><small>Annonces publiques · pool ${listening[2].length}.</small></button><button class="practice-card" data-part="3"><strong>Partie 3 · a / b / c</strong><small>Messages et conversations · pool ${listening[3].length}.</small></button><button class="practice-card" data-part="4"><strong>Supplément · reconnaître les situations</strong><small>Lieu, intention et service · pool ${listening[4].length}.</small></button></div>`;
  document.getElementById('backPractice').onclick=renderPractice;document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>startListeningPractice(+b.dataset.part));
  practiceProgress.decorate();
}

function startListeningPractice(part){
  const tasks=shuffle(listening[part]).slice(0,10);let i=0,score=0;
  function next(ok){if(typeof ok==='boolean'){if(ok)score++;i++;}if(i>=tasks.length){A1Streak.completeExercise();const pct=Math.round(score/tasks.length*100);view.innerHTML=`<section class="card center"><span class="pill ${pct>=70?'green':'amber'}">HÖREN · ${part===4?'ZUSATZ':'TEIL '+part}</span><div class="score">${pct}%</div><h2>${score}/${tasks.length}</h2><p class="muted">Une nouvelle ronde tire une autre sélection du pool.</p><div class="button-row"><button class="secondary-btn" id="againHear">Recommencer</button><button class="primary-btn" id="backHearMenu">Hören</button></div></section>`;document.getElementById('againHear').onclick=()=>startListeningPractice(part);document.getElementById('backHearMenu').onclick=renderListeningMenu;return;}renderListeningTask(part,tasks[i],false,next,`${i+1}/${tasks.length}`);}
  next();
}

function renderListeningTask(part,item=null,examMode=false,onDone=null,progressLabel=''){
  const task=item||randomItem(listening[part]);let plays=0,answered=false;const maxPlays=part===2?1:2;
  function draw(){
    const options=part===2?['Richtig','Falsch']:task.o;
    view.innerHTML=`<div class="between"><button class="tiny-btn" id="backHear">← Hören</button><span class="pill">${progressLabel||'Teil '+part}</span></div><section class="card" style="margin-top:12px"><div class="audio-panel"><button class="speak-btn large" id="playAudio">▶️</button><div><strong>Audio abspielen</strong></div><div class="play-count">${examMode?`${plays}/${maxPlays} écoute(s) utilisée(s)`:'Mode entraînement · répétition libre'}</div></div><div class="quiz-q">${esc(part===2?task.statement:task.q)}</div><div class="options">${options.map((x,j)=>`<button class="option-btn" data-o="${j}">${esc(x)}</button>`).join('')}</div><div id="hearFeedback"></div></section>`;
    document.getElementById('backHear').onclick=()=>examMode?renderExam():renderListeningMenu();
    document.getElementById('playAudio').onclick=()=>{if(examMode&&plays>=maxPlays)return;plays++;speak(task.speech,true,.78);if(examMode){document.querySelector('.play-count').textContent=`${plays}/${maxPlays} écoute(s) utilisée(s)`;if(plays>=maxPlays)document.getElementById('playAudio').disabled=true;}};
    document.querySelectorAll('[data-o]').forEach(btn=>btn.onclick=()=>{if(answered)return;answered=true;practiceProgress.record('listening',task.id);const chosen=+btn.dataset.o,correctIndex=part===2?(task.a?0:1):task.a,ok=chosen===correctIndex;if(ok){if(!state.masteredListening.includes(task.id)){state.masteredListening.push(task.id);save();}}document.querySelectorAll('[data-o]').forEach((b,j)=>{b.disabled=true;if(j===correctIndex)b.classList.add('correct');else if(j===chosen)b.classList.add('wrong');});document.getElementById('hearFeedback').innerHTML=`<div class="feedback ${ok?'good':'bad'}">${ok?'✓ Correct':'✗ À revoir'}</div>${examMode?'':`<div class="transcript"><strong>Transcription :</strong><br>${esc(task.speech)}</div>`}<div class="spacer"></div><button class="primary-btn" id="nextHear">${onDone?'Continuer':'Nouvelle tâche'}</button>`;document.getElementById('nextHear').onclick=()=>{if(onDone)onDone(ok);else renderListeningTask(part);};});
  }
  draw();
}

function renderReadingMenu(){
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backPractice">← Entraîner</button><span class="pill">📖 Lesen</span></div><section class="card hero" style="margin-top:12px"><h2>Leseverstehen</h2><p class="muted">Chaque ronde contient 10 tâches : messages, annonces, panneaux et données pratiques.</p></section><div class="list"><button class="practice-card" data-rpart="1"><strong>Teil 1 · kurze Nachrichten</strong><small>Richtig/Falsch · pool ${reading[1].length}.</small></button><button class="practice-card" data-rpart="2"><strong>Partie 2 · Demander des informations finden</strong><small>Deux annonces/sites · pool ${reading[2].length}.</small></button><button class="practice-card" data-rpart="3"><strong>Teil 3 · Schilder & Hinweise</strong><small>Richtig/Falsch · pool ${reading[3].length}.</small></button><button class="practice-card" data-rpart="4"><strong>Zusatz · Tabellen & Fahrpläne</strong><small>Horaires, prix et programmes · pool ${reading[4].length}.</small></button></div>`;
  document.getElementById('backPractice').onclick=renderPractice;document.querySelectorAll('[data-rpart]').forEach(b=>b.onclick=()=>startReadingPractice(+b.dataset.rpart));
  practiceProgress.decorate();
}

function startReadingPractice(part){
  const tasks=shuffle(reading[part]).slice(0,10);let i=0,score=0;
  function next(ok){if(typeof ok==='boolean'){if(ok)score++;i++;}if(i>=tasks.length){A1Streak.completeExercise();const pct=Math.round(score/tasks.length*100);view.innerHTML=`<section class="card center"><span class="pill ${pct>=70?'green':'amber'}">LESEN · ${part===4?'ZUSATZ':'TEIL '+part}</span><div class="score">${pct}%</div><h2>${score}/${tasks.length}</h2><p class="muted">Une nouvelle ronde tire une autre sélection du pool.</p><div class="button-row"><button class="secondary-btn" id="againRead">Recommencer</button><button class="primary-btn" id="backReadMenu">Lesen</button></div></section>`;document.getElementById('againRead').onclick=()=>startReadingPractice(part);document.getElementById('backReadMenu').onclick=renderReadingMenu;return;}renderReadingTask(part,tasks[i],false,next,`${i+1}/${tasks.length}`);}
  next();
}

function renderReadingTask(part,item=null,examMode=false,onDone=null,progressLabel=''){
  const task=item||randomItem(reading[part]);let body='',options=[],correct=0,audio='';
  if(part===1){body=`<div class="reading-text">${esc(task.text)}</div><div class="quiz-q">${esc(task.statement)}</div>`;options=['Richtig','Falsch'];correct=task.a?0:1;audio=task.statement;}
  if(part===2){body=`<div class="notice"><strong>Situation :</strong> ${esc(task.need)}</div><div class="ad-grid" style="margin-top:12px"><div class="ad-box"><strong>A</strong>${esc(task.aText)}</div><div class="ad-box"><strong>B</strong>${esc(task.bText)}</div></div><div class="quiz-q">Wo finden Sie die passende Information?</div>`;options=['A','B'];correct=task.a;audio=task.audio||(task.a===0?task.aText:task.bText);}
  if(part===3){body=`<div class="muted" style="margin-bottom:8px">${esc(task.where)}</div><div class="sign">${esc(task.sign).replace(/\n/g,'<br>')}</div><div class="quiz-q">${esc(task.statement)}</div>`;options=['Richtig','Falsch'];correct=task.a?0:1;audio=task.statement;}
  if(part===4){body=`<div class="reading-text">${esc(task.text).replace(/\n/g,'<br>')}</div><div class="quiz-q">${esc(task.q)}</div>`;options=task.o;correct=task.a;audio=task.audio||task.o[task.a];}
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backRead">← Lesen</button><span class="pill">${progressLabel||'Teil '+part}</span></div><section class="card" style="margin-top:12px">${body}<div class="options">${options.map((x,j)=>`<button class="option-btn" data-o="${j}">${esc(x)}</button>`).join('')}</div><div id="readFeedback"></div></section>`;
  document.getElementById('backRead').onclick=()=>examMode?renderExam():renderReadingMenu();document.querySelectorAll('[data-o]').forEach(btn=>btn.onclick=()=>{practiceProgress.record('reading',task.id);const chosen=+btn.dataset.o,ok=chosen===correct;if(ok){if(!state.masteredReading.includes(task.id)){state.masteredReading.push(task.id);save();}}document.querySelectorAll('[data-o]').forEach((b,j)=>{b.disabled=true;if(j===correct)b.classList.add('correct');else if(j===chosen)b.classList.add('wrong');});document.getElementById('readFeedback').innerHTML=`<div class="feedback ${ok?'good':'bad'}">${ok?'✓ Correct':'✗ La bonne réponse est '+esc(options[correct])}</div><div class="spacer"></div><button class="primary-btn" id="nextRead">${onDone?'Continuer':'Nouvelle tâche'}</button>`;document.getElementById('nextRead').onclick=()=>{if(onDone)onDone(ok);else renderReadingTask(part);};});
}

function renderWritingMenu(){
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backPractice">← Entraîner</button><span class="pill">✍️ Schreiben</span></div><section class="card hero" style="margin-top:12px"><h2>Schreiben</h2><p class="muted">Formulaires avec 10 informations pour automatiser les données personnelles, puis messages courts selon la grille Goethe fournie.</p></section><div class="grid"><button class="practice-card" id="formPractice"><span class="icon">▦</span><strong>Teil 1 · Formulare</strong><small>${formTasks.length} scénarios · 10 champs chacun.</small></button><button class="practice-card" id="emailPractice"><span class="icon">✉️</span><strong>Teil 2 · Kurze Nachricht</strong><small>${emailTasks.length} sujets + grille 10 points.</small></button></div>`;
  document.getElementById('backPractice').onclick=renderPractice;document.getElementById('formPractice').onclick=()=>renderFormTask();document.getElementById('emailPractice').onclick=()=>renderEmailTask();
  practiceProgress.decorate();
}

function renderFormTask(task=null,onDone=null){
  task=task||randomItem(formTasks);const total=task.fields.length;
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backWrite">← Schreiben</button><span class="pill">Teil 1 · Formular</span></div><section class="card" style="margin-top:12px"><h2>${esc(task.title)}</h2><p>${esc(task.scenario)}</p><div class="form-grid">${task.fields.map((f,i)=>`<div class="field"><label>${esc(f.label)}</label><input class="text-input" id="field${i}" autocomplete="off"></div>`).join('')}</div><div class="spacer"></div><button class="primary-btn" id="checkForm">Vérifier les ${total} réponses</button><div id="formFeedback"></div></section>`;
  document.getElementById('backWrite').onclick=renderWritingMenu;document.getElementById('checkForm').onclick=()=>{if(task.fields.every((_,i)=>document.getElementById('field'+i).value.trim()))A1Streak.completeExercise();let correct=0;const details=task.fields.map((f,i)=>{const val=normalize(document.getElementById('field'+i).value);const ok=f.answers.some(a=>normalize(a)===val);if(ok)correct++;return `<div>${ok?'✓':'✗'} <strong>${esc(f.label)}:</strong> ${ok?'correct':esc(f.answers[0])}</div>`;}).join('');const pct=Math.round(correct/total*100);if(pct>=70&&!state.writingDone.includes(task.id)){state.writingDone.push(task.id);save();}document.getElementById('formFeedback').innerHTML=`<div class="feedback ${pct>=70?'good':'bad'}"><strong>${correct}/${total}</strong><div style="margin-top:8px;line-height:1.7">${details}</div></div><div class="spacer"></div><button class="primary-btn" id="nextForm">${onDone?'Continuer':'Nouveau formulaire'}</button>`;document.getElementById('nextForm').onclick=()=>onDone?onDone(correct):renderFormTask();};
}

function renderEmailTask(task=null,onDone=null){
  task=task||randomItem(emailTasks);view.innerHTML=`<div class="between"><button class="tiny-btn" id="backWrite">← Schreiben</button><span class="pill">Teil 2 · Nachricht</span></div><section class="card" style="margin-top:12px"><h2>Écris à ${esc(task.to)}</h2><p>${esc(task.situation)}</p><div class="notice"><strong>3 Inhaltspunkte</strong><br>• ${task.points.map(esc).join('<br>• ')}</div><div class="spacer"></div><textarea class="text-area" id="emailText" placeholder="Écris ton message en allemand…"></textarea><div class="word-count" id="wordCount">0 Wörter</div><button class="primary-btn" id="openRubric">Ouvrir la grille d’auto-évaluation</button><div id="emailFeedback"></div></section>`;
  const ta=document.getElementById('emailText'),wc=document.getElementById('wordCount');ta.oninput=()=>{wc.textContent=`${A1Learning.countWords(ta.value)} mots`;document.getElementById('emailFeedback').replaceChildren();};document.getElementById('backWrite').onclick=renderWritingMenu;document.getElementById('openRubric').onclick=()=>{const words=A1Learning.countWords(ta.value);document.getElementById('emailFeedback').innerHTML=`<hr class="soft"><h3>Selbsteinschätzung · 10 Punkte</h3><p class="muted">Coche uniquement ce que ton texte accomplit clairement. 3 points par contenu + 1 point pour une forme de message appropriée. Ce score est une aide d’entraînement, pas une correction officielle.</p><div class="checklist">${task.points.map((p,i)=>`<label class="check-item"><input type="checkbox" data-score="3"><span><strong>3 P.</strong> ${esc(p)}</span></label>`).join('')}<label class="check-item"><input type="checkbox" data-score="1"><span><strong>1 P.</strong> J’ai une formule d’appel et une salutation adaptées.</span></label></div><div class="notice ${words>=25?'success':'warning'}" style="margin-top:12px">Ton texte contient <strong>${words} mots</strong>. La consigne officielle demande environ 30 mots.</div><div class="spacer"></div><button class="secondary-btn" id="calcWrite">Calculer mon score</button><div id="writeScore"></div><div class="spacer"></div><button class="soft-btn" id="showModel">Voir un exemple de réponse</button><div id="modelAnswer"></div>`;document.getElementById('calcWrite').onclick=()=>{const words=A1Learning.countWords(ta.value);if(words>=25)A1Streak.completeExercise();const pts=[...document.querySelectorAll('[data-score]')].reduce((s,c)=>s+(c.checked?+c.dataset.score:0),0);if(pts>=7&&words>=25&&!state.writingDone.includes(task.id)){state.writingDone.push(task.id);save();}document.getElementById('writeScore').innerHTML=`<div class="feedback ${pts>=7&&words>=25?'good':'bad'}"><strong>${pts}/10</strong> · auto-évaluation</div>${onDone?'<div class="spacer"></div><button class="primary-btn" id="continueWrite">Continuer</button>':'<div class="spacer"></div><button class="primary-btn" id="nextEmail">Nouveau sujet</button>'}`;const b=document.getElementById(onDone?'continueWrite':'nextEmail');b.onclick=()=>onDone?onDone(pts):renderEmailTask();};document.getElementById('showModel').onclick=()=>document.getElementById('modelAnswer').innerHTML=`<div class="solution"><strong>Beispiel:</strong><br>${esc(task.model).replace(/\n/g,'<br>')}</div>`;};
}

function renderSpeakingMenu(){
  view.innerHTML=`<div class="between"><button class="tiny-btn" id="backPractice">← Entraîner</button><span class="pill">🎤 Oral</span></div><section class="card hero" style="margin-top:12px"><h2>Oral</h2><p class="muted">Le format officiel a trois parties. Ici, chaque ronde d’entraînement propose environ 10 cartes/questions pour développer l’automatisme.</p></section><div class="list"><button class="practice-card" data-spart="1"><strong>Partie 1 · Se présenter</strong><small>${interviewQuestions.length} questions personnelles · 10 par ronde.</small></button><button class="practice-card" data-spart="2"><strong>Partie 2 · Demander des informations</strong><small>${totalInfoCards()} cartes · 10 par ronde.</small></button><button class="practice-card" data-spart="3"><strong>Partie 3 · Formuler des demandes</strong><small>${requestCards.length} demandes · 10 par ronde.</small></button></div><section class="notice warning">L’enregistrement micro fonctionne surtout sur <strong>HTTPS</strong> (par ex. GitHub Pages).</section>`;
  document.getElementById('backPractice').onclick=renderPractice;document.querySelectorAll('[data-spart]').forEach(b=>b.onclick=()=>{const p=+b.dataset.spart;if(p===1)renderSpeakingIntro();if(p===2)renderSpeakingInfo();if(p===3)renderSpeakingRequests();});
  practiceProgress.decorate();
}

function recorderUI(id){return `<div class="recorder"><button class="secondary-btn" id="startRec${id}">● Enregistrer</button><button class="soft-btn" id="stopRec${id}" disabled>■ Stop</button></div><div class="record-status" id="recStatus${id}" role="status"></div><div class="playback" id="playback${id}"></div>`;}
function wireRecorder(id,onRecorded){return A1Learning.wireRecorder(id,()=>{A1Streak.completeExercise();if(onRecorded)onRecorded();},{"unavailable": "Micro non disponible. Utilise HTTPS et un navigateur compatible.", "denied": "Le microphone n’a pas pu être ouvert. Vérifie HTTPS et les permissions.", "recording": "● Enregistrement en cours…", "done": "Enregistrement terminé. Écoute ta réponse.", "empty": "Aucun son enregistré. Essaie de nouveau."});}

function renderSpeakingIntro(){
  const cards=shuffle(interviewQuestions).slice(0,10);let i=0;
  function draw(){
    if(i>=cards.length){view.innerHTML=`<section class="card center"><span class="pill green">10 QUESTIONS TERMINÉES</span><h2>Partie 1 · Se présenter</h2><p class="muted">Écoute tes enregistrements : les réponses doivent être simples, claires et compréhensibles.</p><div class="button-row"><button class="secondary-btn" id="againIntro">10 nouvelles questions</button><button class="primary-btn" id="backSpeak">Sprechen</button></div></section>`;document.getElementById('againIntro').onclick=renderSpeakingIntro;document.getElementById('backSpeak').onclick=renderSpeakingMenu;return;}
    const card=cards[i];view.innerHTML=`<div class="between"><button class="tiny-btn" id="backSpeak">← Sprechen</button><span class="pill">${i+1}/${cards.length}</span></div><section class="card" style="margin-top:12px"><div class="speaking-card"><div class="theme">Question de l’examinateur</div><div class="cue" style="font-size:24px">${esc(card.q)}</div>${speakBtn(card.q)}<p class="muted">Réponds en une ou deux phrases simples.</p>${recorderUI('Intro')}<div class="spacer"></div><button class="soft-btn" id="showIntroModel">Exemple</button><div id="introModel"></div><div class="spacer"></div><button class="primary-btn" id="nextIntro">Suivant</button></div></section>`;document.getElementById('backSpeak').onclick=renderSpeakingMenu;document.getElementById('showIntroModel').onclick=()=>{document.getElementById('introModel').innerHTML=`<div class="solution">${esc(card.a)} ${speakBtn(card.a)}</div>`;wireSpeakButtons();};document.getElementById('nextIntro').onclick=()=>{i++;draw();};wireSpeakButtons();wireRecorder('Intro',()=>{const id='intro-'+card.q;if(!state.speakingDone.includes(id)){state.speakingDone.push(id);save();}});if(audioEnabled)setTimeout(()=>speak(card.q),180);
  }
  draw();
}

function renderSpeakingInfo(){
  const cards=shuffle(speakingTopics.flatMap(t=>t.cards.map(c=>({...c,theme:t.theme})))).slice(0,10);let i=0;
  function draw(){
    if(i>=cards.length){view.innerHTML=`<section class="card center"><span class="pill green">10 CARTES TERMINÉES</span><h2>Partie 2 · Demander des informations</h2><p class="muted">Objectif : formuler rapidement une question simple et compréhensible à partir d’un mot-clé.</p><div class="button-row"><button class="secondary-btn" id="againInfo">10 nouvelles cartes</button><button class="primary-btn" id="backSpeak">Sprechen</button></div></section>`;document.getElementById('againInfo').onclick=renderSpeakingInfo;document.getElementById('backSpeak').onclick=renderSpeakingMenu;return;}
    const card=cards[i];view.innerHTML=`<div class="between"><button class="tiny-btn" id="backSpeak">← Sprechen</button><span class="pill">${i+1}/${cards.length}</span></div><section class="card" style="margin-top:12px"><h2>Demander une information</h2><div class="speaking-card"><div class="theme">Thème : ${esc(card.theme)}</div><div class="cue">${esc(card.cue)}</div></div><p class="muted">Formule une question qui correspond au thème et au mot.</p>${recorderUI('Info')}<div class="spacer"></div><button class="soft-btn" id="showInfoModel">Exemple de question + réponse</button><div id="infoModel"></div><div class="spacer"></div><button class="primary-btn" id="nextInfo">Suivant</button></section>`;document.getElementById('backSpeak').onclick=renderSpeakingMenu;document.getElementById('showInfoModel').onclick=()=>{document.getElementById('infoModel').innerHTML=`<div class="solution"><strong>Question :</strong> ${esc(card.q)} ${speakBtn(card.q)}<br><br><strong>Réponse :</strong> ${esc(card.a)} ${speakBtn(card.a)}</div>`;wireSpeakButtons();};document.getElementById('nextInfo').onclick=()=>{i++;draw();};wireRecorder('Info',()=>{const id='info-'+card.theme+'-'+card.cue;if(!state.speakingDone.includes(id)){state.speakingDone.push(id);save();}});
  }
  draw();
}

function renderSpeakingRequests(){
  const cards=shuffle(requestCards).slice(0,10);let i=0;
  function draw(){
    if(i>=cards.length){view.innerHTML=`<section class="card center"><span class="pill green">10 DEMANDES TERMINÉES</span><h2>Partie 3 · Formuler des demandes</h2><p class="muted">Entraîne-toi à formuler de courtes demandes polies et des réponses adaptées.</p><div class="button-row"><button class="secondary-btn" id="againReq">10 nouvelles cartes</button><button class="primary-btn" id="backSpeak">Sprechen</button></div></section>`;document.getElementById('againReq').onclick=renderSpeakingRequests;document.getElementById('backSpeak').onclick=renderSpeakingMenu;return;}
    const card=cards[i];view.innerHTML=`<div class="between"><button class="tiny-btn" id="backSpeak">← Sprechen</button><span class="pill">${i+1}/${cards.length}</span></div><section class="card" style="margin-top:12px"><h2>Formuler des demandes</h2><p class="muted">Fais une demande polie à partir de la carte, puis formule une réponse adaptée.</p><div class="speaking-card"><div class="theme">Carte d’action</div><div class="cue">${esc(card.cue)}</div></div>${recorderUI('Req')}<div class="spacer"></div><button class="soft-btn" id="showReqModel">Afficher un exemple</button><div id="reqModel"></div><div class="spacer"></div><button class="primary-btn" id="nextReq">Suivant</button></section>`;document.getElementById('backSpeak').onclick=renderSpeakingMenu;document.getElementById('showReqModel').onclick=()=>{document.getElementById('reqModel').innerHTML=`<div class="solution"><strong>Demande :</strong> ${esc(card.request)} ${speakBtn(card.request)}<br><br><strong>Réponse :</strong> ${esc(card.response)} ${speakBtn(card.response)}</div>`;wireSpeakButtons();};document.getElementById('nextReq').onclick=()=>{i++;draw();};wireRecorder('Req',()=>{const id='req-'+card.cue;if(!state.speakingDone.includes(id)){state.speakingDone.push(id);save();}});
  }
  draw();
}

function renderExam(){
  view.innerHTML=`<section class="card hero"><span class="pill">MODE EXAMEN</span><h2 style="margin-top:12px">Simulation A1</h2><p class="muted">Les sections reprennent le volume et la structure des documents officiels. Pour la compréhension orale et la compréhension écrite, la simulation tire des tâches nouvelles de façon aléatoire.</p></section><section class="card exam-structure"><div class="exam-line"><strong>Écoute</strong><small>6 + 4 + 5 tâches</small><button class="tiny-btn" id="examHear">Démarrer</button></div><div class="exam-line"><strong>Lecture</strong><small>5 + 5 + 5 tâches</small><button class="tiny-btn" id="examRead">Démarrer</button></div><div class="exam-line"><strong>Écriture</strong><small>1 formulaire + 1 message</small><button class="tiny-btn" id="examWrite">Démarrer</button></div><div class="exam-line"><strong>Oral</strong><small>3 parties guidées</small><button class="tiny-btn" id="examSpeak">Démarrer</button></div></section><section class="card"><h3>Simulation rapide · 30 questions</h3><p class="muted">15 tâches de compréhension orale + 15 tâches de compréhension écrite, avec limites de répétition audio. À la fin tu reçois un score d’entraînement.</p><button class="primary-btn" id="quickMock">Démarrer la simulation</button></section><section class="card"><h3>Bilan du cours A1</h3><p class="muted">Revoir les 24 leçons en quatre blocs de 30 questions.</p><button class="primary-btn exercise-start-btn" id="courseMastery">Commencer le bilan</button></section><section class="notice">Le score affiché est un <strong>score d’entraînement</strong>. L’évaluation officielle de l’expression écrite et de l’expression orale dépend aussi de la réalisation communicative et est faite par des examinateurs.</section>`;
  document.getElementById('examHear').onclick=()=>startListeningSection();document.getElementById('examRead').onclick=()=>startReadingSection();document.getElementById('examWrite').onclick=()=>startWritingSection();document.getElementById('examSpeak').onclick=()=>startSpeakingSection();document.getElementById('quickMock').onclick=startQuickMock;document.getElementById('courseMastery').onclick=()=>DE_A1_ASSESSMENTS.renderCourseMenu({view,state,save,onBack:renderExam,speak});
}

function makeListeningSet(){return [...shuffle(listening[1]).slice(0,6).map(t=>({part:1,t})),...shuffle(listening[2]).slice(0,4).map(t=>({part:2,t})),...shuffle(listening[3]).slice(0,5).map(t=>({part:3,t}))];}
function makeReadingSet(){return [...shuffle(reading[1]).slice(0,5).map(t=>({part:1,t})),...shuffle(reading[2]).slice(0,5).map(t=>({part:2,t})),...shuffle(reading[3]).slice(0,5).map(t=>({part:3,t}))];}
function startListeningSection(){const set=makeListeningSet();let i=0,score=0;function next(ok){if(ok)score++;i++;if(i<set.length){const x=set[i];renderListeningTask(x.part,x.t,true,next);}else showSectionResult('Hören',score,set.length,startListeningSection);}const x=set[0];renderListeningTask(x.part,x.t,true,next);}
function startReadingSection(){const set=makeReadingSet();let i=0,score=0;function next(ok){if(ok)score++;i++;if(i<set.length){const x=set[i];renderReadingTask(x.part,x.t,true,next);}else showSectionResult('Lesen',score,set.length,startReadingSection);}const x=set[0];renderReadingTask(x.part,x.t,true,next);}
function showSectionResult(name,score,total,retry){A1Streak.completeExercise();const pct=Math.round(score/total*100);const labels={Hören:'Écoute',Lesen:'Lecture'};view.innerHTML=`<section class="card center"><span class="pill">${labels[name]||name}</span><div class="score">${pct}%</div><h2>${score}/${total}</h2><p class="muted">Résultat d’entraînement pour cette section.</p><div class="button-row"><button class="secondary-btn" id="retrySec">Recommencer</button><button class="primary-btn" id="backExam">Examen</button></div></section>`;document.getElementById('retrySec').onclick=retry;document.getElementById('backExam').onclick=renderExam;}
function startWritingSection(){const base=randomItem(formTasks),f={...base,fields:shuffle(base.fields).slice(0,5)},e=randomItem(emailTasks);renderFormTask(f,()=>renderEmailTask(e,()=>{view.innerHTML=`<section class="card center"><h2>Écriture terminée ✓</h2><p class="muted">Simulation : 5 informations dans le formulaire, puis un message court avec 3 points de contenu.</p><button class="primary-btn" id="backExam">Retour à l’examen</button></section>`;document.getElementById('backExam').onclick=renderExam;}));}
function startSpeakingSection(){renderSpeakingIntro();const note=document.createElement('div');note.className='notice';note.style.marginTop='12px';note.innerHTML='Mode simulation : après la partie 1, utilise ensuite les parties 2 et 3 depuis le menu Oral. Le navigateur ne peut pas noter officiellement ta prononciation.';view.appendChild(note);}
function startQuickMock(){const set=[...makeListeningSet().map(x=>({...x,kind:'H'})),...makeReadingSet().map(x=>({...x,kind:'L'}))];let i=0,score=0;function next(ok){if(ok)score++;i++;if(i<set.length)draw();else finish();}function draw(){const x=set[i];const badge=document.createElement('div');if(x.kind==='H')renderListeningTask(x.part,x.t,true,next);else renderReadingTask(x.part,x.t,true,next);const top=view.querySelector('.between .pill');if(top)top.textContent=`${x.kind==='H'?'Écoute':'Lecture'} · ${i+1}/30`;}
  function finish(){const pct=Math.round(score/30*100);state.bestMock=Math.max(state.bestMock,pct);save(true);view.innerHTML=`<section class="card center"><span class="pill ${pct>=60?'green':'amber'}">SIMULATION RAPIDE</span><div class="score">${pct}%</div><h2>${score}/30</h2><p class="muted">Compréhension orale + compréhension écrite. Pour une préparation complète, fais aussi l’expression écrite et l’expression orale séparément.</p><div class="button-row"><button class="secondary-btn" id="againMock">Recommencer</button><button class="primary-btn" id="backExam">Examen</button></div></section>`;document.getElementById('againMock').onclick=startQuickMock;document.getElementById('backExam').onclick=renderExam;}
  draw();
}

navButtons.forEach(b=>b.onclick=()=>setRoute(b.dataset.route));
A1Voice.mount({lang:'de-DE',uiLang:'fr'});
audioToggle.onclick=()=>{audioEnabled=!audioEnabled;localStorage.setItem('deA1AudioEnabled',String(audioEnabled));updateAudioButton();if(audioEnabled)speak('Guten Tag! Willkommen beim Deutschtraining.',true);else A1Voice.cancel();};
window.A1ResetCourseProgress=async()=>{
  const fresh=JSON.parse(JSON.stringify(defaultState));
  await A1Profile.resetProgress('deutsch-a1',fresh);
  localStorage.removeItem(A1Profile.namespacedKey('deA1VocabIndex'));
  A1Voice.cancel();state=fresh;setRoute('home');
};
if('serviceWorker'in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js', {updateViaCache:'none'}).then(registration=>registration.update()).catch(()=>{}));}

DE_A1_ASSESSMENTS.configure({lessons,grammarSets,practiceProgress});
updateAudioButton();setRoute('home');
